cd ~/captures; python3 -c "
from PIL import Image; import numpy as np
from scipy import ndimage
for f in ['wrist_001.png','wrist_002.png','wrist_003.png']:
  a=np.array(Image.open(f).convert('L')).astype(int)
  m=a<70; l,n=ndimage.label(m)
  for i in range(1,n+1):
    ys,xs=np.nonzero(l==i)
    if len(xs)<5000: print(f,i,len(xs),xs.mean().round(2),ys.mean().round(2))
"

