cd ~/captures; python3 -c "
from PIL import Image
for f in ['wrist_001.png','wrist_002.png','wrist_003.png']:
  im=Image.open(f).convert('L'); w,h=im.size; p=im.load()
  # bore near bottom: region y>340, x 200..600
  xs=[];ys=[]
  for y in range(340,h):
    for x in range(180,600):
      if p[x,y]<70: xs.append(x);ys.append(y)
  print(f,len(xs),sum(xs)/max(1,len(xs)),sum(ys)/max(1,len(ys)))
"

